'use strict';
let worldLand=[];
const worldLandReady=fetch('data/world-land.json').then(r=>{if(!r.ok)throw Error('World map data is unavailable.');return r.json()}).then(data=>{worldLand=data;draw();return data});worldLandReady.catch(()=>{});
const propsBeforeShapes=prop;prop=function(c,o,v){if(o.type!=='shape')return propsBeforeShapes(c,o,v);const w=o.width||160,h=o.height||100;c.save();c.translate(v.x,v.y);c.rotate(v.rotation*Math.PI/180);c.scale(v.scale,v.scale);c.globalAlpha=v.opacity;const color=o.color||'#54766a';if(o.shape==='ellipse')ellipse(c,0,0,w/2,h/2,color);else if(o.shape==='line')line(c,-w/2,0,w/2,0,color,Math.max(2,h));else if(o.shape==='pin'){circle(c,0,-h*.15,Math.min(w,h)*.35,color);c.fillStyle=color;c.beginPath();c.moveTo(-w*.2,0);c.lineTo(0,h*.5);c.lineTo(w*.2,0);c.closePath();c.fill();circle(c,0,-h*.15,Math.min(w,h)*.12,'#fff5e5')}else if(o.shape==='map'){c.fillStyle=color;for(const polygon of worldLand){c.beginPath();for(const ring of polygon)ring.forEach(([lon,lat],i)=>{const x=lon/360*w,y=-lat/180*h;i?c.lineTo(x,y):c.moveTo(x,y)});c.closePath();c.fill('evenodd')}}else if(o.shape==='chart'){const rows=o.data||[],max=Math.max(1,...rows.map(d=>d.value)),plotHeight=h-55,gap=w/Math.max(1,rows.length),bar=Math.min(90,gap*.58);line(c,-w/2,h/2-35,w/2,h/2-35,'#8c9b8e',1);rows.forEach((d,i)=>{const height=d.value/max*(plotHeight-25),x=-w/2+gap*(i+.5);rect(c,x-bar/2,h/2-35-height,bar,height,i%2?o.accent||'#dca444':color,5);c.fillStyle='#31564d';c.font='600 18px Arial';c.textAlign='center';c.fillText(String(d.value),x,h/2-45-height);c.font='14px Arial';c.fillText(d.label.slice(0,18),x,h/2-10)})}else{rect(c,-w/2,-h/2,w,h,color,o.shape==='rounded'||o.shape==='bubble'?18:2);if(o.shape==='bubble'){c.fillStyle=color;c.beginPath();c.moveTo(-w*.25,h/2-1);c.lineTo(-w*.35,h/2+28);c.lineTo(-w*.05,h/2-1);c.closePath();c.fill()}}c.restore()};
const boundsBeforeShapes=bounds;bounds=function(o,v){if(o.type!=='shape')return boundsBeforeShapes(o,v);return{x:v.x-o.width*v.scale/2,y:v.y-o.height*v.scale/2,w:o.width*v.scale,h:o.height*v.scale+(o.shape==='bubble'?28*v.scale:0)}};
const packs=[{id:'chart',name:'Data story',caption:'Editable chart and headline'},{id:'comparison',name:'Side by side',caption:'Two cards for clear comparisons'},{id:'timeline',name:'Milestone timeline',caption:'Four editable milestones'},{id:'map',name:'Map & locations',caption:'World map and movable pins'},{id:'callout',name:'Presenter callout',caption:'Character, quote and pointer'},{id:'lowerthird',name:'Lower third',caption:'Animated name and role banner'}];
$('sceneTab').insertAdjacentHTML('afterbegin','<section class="template-pack"><h3>Explainer template pack</h3><label>Insert<select id="templateInsert"><option value="new">New scene</option><option value="layers">Layers in this scene</option></select></label><div id="templatePacks" class="template-grid"></div></section>');
for(const pack of packs){const button=document.createElement('button');button.dataset.pack=pack.id;button.innerHTML='<b>'+pack.name+'</b><small>'+pack.caption+'</small>';button.onclick=()=>addExplainerTemplate(pack.id).catch(e=>toast(e.message));$('templatePacks').append(button)}
function editableShape(name,shape,x,y,width,height,color='#54766a',extra={}){return templateObject('shape',{name,shape,width,height,color,...extra},x,y)}
function templateText(text,x,y,size=32,color='#31564d'){return templateObject('text',{name:text,text,fontSize:size,color,textFont:'sans'},x,y)}
async function addExplainerTemplate(kind){stop();if(kind==='map')await worldLandReady;const meta=packs.find(p=>p.id===kind);if(!meta)return;const fresh=$('templateInsert').value==='new';if(fresh&&project.scenes.length>=99)return toast('Keep fewer than 100 scenes per project.');const target=fresh?scene(meta.name):current(),objects=[],title=text=>objects.push(templateText(text,480,90,42));if(kind==='chart'){title('A clearer view of the numbers');objects.push(editableShape('Data chart','chart',480,315,700,300,'#54766a',{accent:'#dda642',data:[{label:'Before',value:35},{label:'Today',value:62},{label:'Next',value:88}]}));objects.push(templateText('Change labels and values in the inspector.',480,505,18))}
 if(kind==='comparison'){title('Two paths. One decision.');for(const[x,name,color]of[[255,'Option A','#dce6d7'],[705,'Option B','#f0ddba']]){objects.push(editableShape(name+' card','rounded',x,315,370,320,color),templateText(name,x,215,34),templateText('Your first point',x,295,25),templateText('Your second point',x,345,25),templateText('Your conclusion',x,405,25))}}
 if(kind==='timeline'){title('One step at a time');objects.push(editableShape('Milestone connection','line',480,290,720,4,'#b5c8b7'));for(let i=0;i<4;i++){const x=120+i*240;objects.push(editableShape('Milestone '+(i+1),'ellipse',x,290,56,56,i%2?'#dca444':'#54766a'),templateText(String(i+1),x,300,27,'#fff7e5'),templateText(['Discover','Plan','Create','Share'][i],x,365,24),templateText('Your note',x,410,18))}}
 if(kind==='map'){title('Connect the bigger picture');objects.push(editableShape('World land','map',480,305,760,330,'#7d9c89'));for(const[x,y,label]of[[365,270,'Region A'],[640,350,'Region B']])objects.push(editableShape(label+' pin','pin',x,y,35,48,'#bc6848'),templateText(label,x,y+47,22))}
 if(kind==='callout'){target.template='studio';objects.push(templateObject('character',{character:structuredClone(project.cast[0]||baseChar),expression:'happy',characterLoop:'talk',transitionTag:'presenter'},250,470),editableShape('Quote card','bubble',645,245,480,220,'#dce6d7'),templateText('Make the complex',645,225,34),templateText('feel simple.',645,272,34),templateText('Add your explanation here.',645,385,21))}
 if(kind==='lowerthird'){objects.push(editableShape('Name banner','rounded',310,430,470,105,'#31564d'),templateText('Your name',300,416,32,'#fff7e5'),templateText('Role / channel / topic',300,455,18,'#e6c67e'));for(const o of objects){o.fadeIn=.5;if(o.type==='text'){o.textEffect='rise';o.textDuration=.6}}}
 const group='Template '+uid().slice(0,6);for(const o of objects){o.group=group;if(o.type==='text'&&kind!=='lowerthird'){o.textEffect='fade';o.textDuration=.5}}target.objects.push(...objects);if(fresh){project.scenes.push(target);sceneIndex=project.scenes.length-1;time=0}selectLayers(objects.map(o=>o.id),objects[0]?.id);save();render();toast(meta.name+' added. All text, shapes and chart data are editable.')}
const controlsBeforeShapeEditor=renderControls;renderControls=function(){controlsBeforeShapeEditor();const o=object();if(o?.type!=='shape')return;const panel=document.createElement('details');panel.open=true;panel.innerHTML='<summary>Editable shape</summary><label>Colour<input id="shapeColor" type="color"></label><label>Width<input id="shapeWidth" type="number" min="4" max="1600"></label><label>Height<input id="shapeHeight" type="number" min="2" max="1000"></label>'+(o.shape==='chart'?'<label>Accent<input id="chartAccent" type="color"></label><p class="note">One row per bar: Label | value</p><textarea id="chartData" rows="5"></textarea><button id="applyChartData">Update chart</button>':'');$('controls').prepend(panel);$('shapeColor').value=o.color||'#54766a';$('shapeWidth').value=o.width;$('shapeHeight').value=o.height;$('shapeColor').oninput=e=>{o.color=e.target.value;save();draw()};for(const[id,key,min,max]of[['shapeWidth','width',4,1600],['shapeHeight','height',2,1000]])$(id).onchange=e=>{o[key]=clamp(+e.target.value||min,min,max);save();render()};if(o.shape==='chart'){$('chartAccent').value=o.accent||'#dca444';$('chartAccent').oninput=e=>{o.accent=e.target.value;save();draw()};$('chartData').value=(o.data||[]).map(d=>d.label+' | '+d.value).join('\n');$('applyChartData').onclick=()=>{const rows=$('chartData').value.split('\n').filter(l=>l.trim()).map(line=>{const[label,...parts]=line.split('|');return{label:label.trim(),value:Number(parts.join('|').trim())}});if(!rows.length||rows.length>12||rows.some(d=>!d.label||d.label.length>80||!Number.isFinite(d.value)||d.value<0||d.value>1e9))return toast('Use up to 12 rows: Label | positive value.');o.data=rows;save();draw()}}panel.querySelectorAll('input,textarea,button').forEach(e=>e.disabled=!!o.locked)};
const shapesValidator=valid;valid=function(p){return shapesValidator(p)&&p.scenes.every(s=>s.objects.every(o=>o.type!=='shape'||['rect','rounded','ellipse','line','pin','bubble','map','chart'].includes(o.shape)&&Number.isFinite(o.width)&&o.width>=4&&o.width<=1600&&Number.isFinite(o.height)&&o.height>=2&&o.height<=1000&&/^#[0-9a-f]{6}$/i.test(o.color)&&(o.shape!=='chart'||Array.isArray(o.data)&&o.data.length>=1&&o.data.length<=12&&o.data.every(d=>typeof d.label==='string'&&d.label.length<=80&&Number.isFinite(d.value)&&d.value>=0&&d.value<=1e9))))};
const exportBeforeMapAssets=$('renderVideo').onclick;$('renderVideo').onclick=async()=>{if(project.scenes.some(s=>s.objects.some(o=>o.type==='shape'&&o.shape==='map'))){try{await worldLandReady}catch(e){return toast(e.message)}}return exportBeforeMapAssets()};
render();
